"""Structure discovery on the labelled point model (Part V, phase 1 of the design note).

Everything here is computed from the generator permutations and the solved colouring.
Nothing is specific to one puzzle.

Orbits      Connected components of the points under the moves. Each is one kind of piece
            (or one attribute of a piece), and each can be solved on its own.
Pieces      Within an orbit, the piece of a point p is the set of points that every
            permutation fixing p also fixes. Stickers of one corner, or the residues of one
            counter, come out as one piece. Pieces are blocks of imprimitivity.
Slots       A piece seen as a set of positions. What a slot currently holds is fully
            determined by the label at its first position (its *content*), because fixing
            one point of a piece fixes the rest.
Sub-blocks  Block systems that refine the pieces, e.g. the two diagonals of a 4-sticker
            piece. They give orientation-parity features.
Features    A feature assigns each (slot, content) a class. The classes are functions of the
            *visible* pattern the content shows in that slot, so a feature never depends on
            which of several identical-looking pieces is present. Features are the
            projections that define the rungs of a ladder.

A visible state is decoded into labels slot by slot: the colours a slot shows identify its
content up to pieces that look alike, and the first such content is chosen. Any feature
built here gives the same value for all of those choices.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Callable, Sequence

import numpy as np

from core.perm_model import PointModel


# -- permutation-group primitives --------------------------------------------------

def point_orbits(gens: np.ndarray) -> list[np.ndarray]:
    """Orbits of the points under gather tables ``gens`` (M, n). Sorted by first point."""
    n = gens.shape[1]
    parent = np.arange(n)

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for g in gens:
        for i in range(n):
            a, b = find(i), find(int(g[i]))
            if a != b:
                parent[a] = b
    roots = np.array([find(i) for i in range(n)])
    return [np.nonzero(roots == r)[0] for r in sorted(set(roots.tolist()), key=lambda r: int(np.nonzero(roots == r)[0][0]))]


def _tuple_orbit(gens: np.ndarray, start: tuple[int, ...], limit: int | None = None) -> list[tuple[int, ...]]:
    """Orbit of a tuple of points under the group generated by ``gens`` (image form).
    Stops early and returns what it has once more than ``limit`` tuples are found."""
    seen = {start}
    frontier = [start]
    while frontier:
        nxt = []
        for t in frontier:
            for g in gens:
                u = tuple(int(g[x]) for x in t)
                if u not in seen:
                    seen.add(u)
                    nxt.append(u)
                    if limit is not None and len(seen) > limit:
                        return list(seen)
        frontier = nxt
    return list(seen)


def minimal_block_system(gens: np.ndarray, points: np.ndarray, a: int, b: int) -> np.ndarray:
    """Smallest block system of the transitive action on ``points`` in which a and b share a
    block (Atkinson's algorithm). Returns a block id for every point of ``points``."""
    pos = {int(p): i for i, p in enumerate(points)}
    parent = list(range(len(points)))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    queue = [(pos[a], pos[b])]
    parent[find(pos[b])] = find(pos[a])
    while queue:
        x, y = queue.pop()
        for g in gens:
            gx, gy = find(pos[int(g[points[x]])]), find(pos[int(g[points[y]])])
            if gx != gy:
                parent[gy] = gx
                queue.append((gx, gy))
    roots = [find(i) for i in range(len(points))]
    ids = {r: k for k, r in enumerate(sorted(set(roots)))}
    return np.array([ids[r] for r in roots])


# -- orbit structure -----------------------------------------------------------------

@dataclass
class Orbit:
    index: int
    points: np.ndarray                 # sorted points of the orbit
    pieces: np.ndarray                 # (n_pieces, k) points of each piece, as home labels and as slot positions
    arrangement: np.ndarray            # (n_pieces, n, k) labels at the slot's positions given the label at its first one (-1 if impossible)
    sub_blocks: list[np.ndarray] = field(default_factory=list)   # each (n_pieces, k): sub-block id of every slot position
    n_colours: int = 0
    pattern: np.ndarray | None = None  # (n_pieces, n, k) visible colours shown, -1 where impossible
    decode_keys: list[dict] = field(default_factory=list)        # per slot: pattern tuple -> canonical content label
    slot_of: np.ndarray | None = None        # (n,) slot of each point of the orbit, -1 elsewhere
    index_in_slot: np.ndarray | None = None  # (n,) index of each point inside its slot

    @property
    def n_pieces(self) -> int:
        return self.pieces.shape[0]

    @property
    def k(self) -> int:
        return self.pieces.shape[1]

    @property
    def ref_pos(self) -> np.ndarray:
        return self.pieces[:, 0]


def _find_pieces(img: np.ndarray, orbit: np.ndarray) -> np.ndarray:
    """Pieces of an orbit: for each point p, the points fixed by everything that fixes p."""
    size = len(orbit)
    in_piece_of: dict[int, list[int]] = {}
    assigned: set[int] = set()
    for p in orbit:
        p = int(p)
        if p in assigned:
            continue
        members = [p]
        for q in orbit:
            q = int(q)
            if q == p:
                continue
            # q is fixed by the stabiliser of p iff the pair (p, q) has an orbit as small as p's
            if len(_tuple_orbit(img, (p, q), limit=size)) == size:
                members.append(q)
        in_piece_of[p] = sorted(members)
        assigned.update(members)
    pieces = sorted(in_piece_of.values())
    sizes = {len(x) for x in pieces}
    assert len(sizes) == 1, f"pieces of one orbit have different sizes: {sizes}"
    return np.array(pieces, dtype=np.int64)


def _build_orbit(model: PointModel, img: np.ndarray, index: int, orbit: np.ndarray) -> Orbit:
    n = model.n
    pieces = _find_pieces(img, orbit)
    n_pieces, k = pieces.shape
    slot_of = np.full(n, -1)
    idx_in_slot = np.full(n, -1)
    for b in range(n_pieces):
        slot_of[pieces[b]] = b
        idx_in_slot[pieces[b]] = np.arange(k)

    # Frames: every way a home piece can sit in a slot. The orbit of the ordered piece under
    # the group lists them; tuple entry t is the position where label piece[t] sits.
    arrangement = np.full((n_pieces, n, k), -1, dtype=np.int32)
    for b in range(n_pieces):
        home = tuple(int(x) for x in pieces[b])
        for image in _tuple_orbit(img, home):
            slot = slot_of[image[0]]
            row = np.empty(k, dtype=np.int32)
            for t in range(k):
                assert slot_of[image[t]] == slot, "a piece was split across slots"
                row[idx_in_slot[image[t]]] = home[t]
            arrangement[slot, row[0]] = row

    # Sub-block systems refining the pieces: blocks generated by a point and another point
    # of its own piece.
    sub_blocks: list[np.ndarray] = []
    seen: set[bytes] = set()
    p0 = int(pieces[0, 0])
    for t in range(1, k):
        ids = minimal_block_system(img, orbit, p0, int(pieces[0, t]))
        n_blocks = len(set(ids.tolist()))
        if n_blocks <= n_pieces or n_blocks >= len(orbit):
            continue                                    # the pieces themselves, or trivial
        id_of = dict(zip(orbit.tolist(), ids.tolist()))
        per_slot = np.empty((n_pieces, k), dtype=np.int64)
        for b in range(n_pieces):
            raw = [id_of[int(x)] for x in pieces[b]]
            order = {v: i for i, v in enumerate(dict.fromkeys(raw))}     # by first position
            per_slot[b] = [order[v] for v in raw]
        key = per_slot.tobytes()
        if key not in seen:
            seen.add(key)
            sub_blocks.append(per_slot)

    # Visible pattern each content shows, and the decode table.
    vis = model.visible
    pattern = np.where(arrangement >= 0, vis[np.maximum(arrangement, 0)], -1)
    decode_keys: list[dict] = []
    for b in range(n_pieces):
        table: dict[tuple, int] = {}
        for content in orbit:
            if arrangement[b, content, 0] < 0:
                continue
            key = tuple(int(x) for x in pattern[b, content])
            table.setdefault(key, int(content))          # orbit is sorted: the first is the canonical one
        decode_keys.append(table)

    return Orbit(index=index, points=orbit, pieces=pieces, arrangement=arrangement,
                 sub_blocks=sub_blocks, n_colours=int(vis[orbit].max()) + 1,
                 pattern=pattern, decode_keys=decode_keys, slot_of=slot_of, index_in_slot=idx_in_slot)


# -- features --------------------------------------------------------------------------

@dataclass
class Feature:
    """Per-slot classification of contents. ``table[slot, label]`` is the class of the slot
    when the label sits at its first position (-1 if that cannot happen). Classes are numbered
    densely per slot, so ``radix[slot]`` is the number of values that slot can take."""
    name: str
    orbit: "Orbit"
    table: np.ndarray          # (n_slots, n) int16
    radix: np.ndarray          # (n_slots,) classes per slot
    goal: np.ndarray           # (n_slots,)

    @property
    def ref_pos(self) -> np.ndarray:
        return self.orbit.ref_pos

    @property
    def n_slots(self) -> int:
        return self.table.shape[0]

    @property
    def n_classes(self) -> int:
        return int(self.radix.max())

    def compute(self, lab: np.ndarray) -> np.ndarray:
        """Feature vector(s) of labelled state(s). lab: (..., n) -> (..., n_slots)."""
        content = np.asarray(lab)[..., self.ref_pos]
        return self.table[np.arange(self.n_slots), content]

    def transition(self, gather: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
        """How one permutation acts on feature vectors.

        Returns ``src`` (n_slots,) and ``lut`` (n_slots, n_classes) with
        ``new[s] = lut[s, old[src[s]]]``. Raises if the feature is not closed under the
        permutation, i.e. if two contents of one class are sent to different classes.
        """
        orb = self.orbit
        q = gather[orb.ref_pos]                       # position each slot's first point is filled from
        src = orb.slot_of[q]
        t = orb.index_in_slot[q]
        labels = orb.points
        old_content_ok = orb.arrangement[src][:, labels, 0] >= 0              # (S, n_orb)
        new_content = orb.arrangement[src[:, None], labels[None, :], t[:, None]]
        old_cls = self.table[src][:, labels]
        new_cls = self.table[np.arange(self.n_slots)[:, None], np.maximum(new_content, 0)]
        lut = np.full((self.n_slots, self.n_classes), -1, dtype=np.int16)
        rows = np.broadcast_to(np.arange(self.n_slots)[:, None], old_cls.shape)
        lut[rows[old_content_ok], old_cls[old_content_ok]] = new_cls[old_content_ok]
        if not np.array_equal(lut[rows[old_content_ok], old_cls[old_content_ok]], new_cls[old_content_ok]):
            raise ValueError(f"feature {self.name} is not closed under this permutation")
        return src.astype(np.int16), lut


def _shape(p: Sequence[int]) -> tuple:
    order: dict[int, int] = {}
    return tuple(order.setdefault(x, len(order)) for x in p)


COARSENINGS: dict[str, Callable[[tuple], tuple]] = {
    "full": lambda p: tuple(p),                                            # everything visible
    "multiset": lambda p: tuple(sorted(p)),                                # which piece, not how it is turned
    "shape": _shape,                                                       # which positions show equal colours
    "type": lambda p: tuple(sorted(p.count(c) for c in set(p))),           # how many colours, with what multiplicity
}


def _make_feature(orbit: Orbit, n: int, name: str, classify: Callable[[int, tuple], tuple]) -> Feature:
    table = np.full((orbit.n_pieces, n), -1, dtype=np.int16)
    radix = np.zeros(orbit.n_pieces, dtype=np.int64)
    for b in range(orbit.n_pieces):
        ids: dict[tuple, int] = {}
        for content in orbit.points:
            if orbit.arrangement[b, content, 0] < 0:
                continue
            key = classify(b, tuple(int(x) for x in orbit.pattern[b, content]))
            table[b, content] = ids.setdefault(key, len(ids))
        radix[b] = len(ids)
    goal = table[np.arange(orbit.n_pieces), orbit.ref_pos]
    return Feature(name=name, orbit=orbit, table=table, radix=radix, goal=goal.copy())


# -- the whole structure ---------------------------------------------------------------

@dataclass
class Structure:
    model: PointModel
    orbits: list[Orbit]            # non-trivial orbits only
    fixed_points: np.ndarray
    orbit_of_point: np.ndarray     # (n,) index into ``orbits`` or -1

    def decode(self, state: np.ndarray) -> np.ndarray:
        """Labelled state consistent with a visible state. Identical-looking pieces are
        assigned the first candidate, so the result need not be a permutation; every feature
        built by this module is the same for all consistent assignments."""
        colours = self.model.state_to_colours(np.asarray(state))
        lab = np.arange(self.model.n, dtype=np.int32)
        for orb in self.orbits:
            for b in range(orb.n_pieces):
                key = tuple(int(x) for x in colours[orb.pieces[b]])
                content = orb.decode_keys[b].get(key)
                if content is None:
                    raise ValueError(f"slot {b} of orbit {orb.index} shows a pattern no piece can show: {key}")
                lab[orb.pieces[b]] = orb.arrangement[b, content]
        return lab

    def feature(self, orbit: int, kind: str, mask: Sequence[int] | None = None) -> Feature:
        """Feature of one orbit.

        ``kind`` is a coarsening name (see COARSENINGS), or ``sub<i>`` for the i-th sub-block
        system (the multiset of colours inside each sub-block).

        ``mask`` lists the colours that stay visible; every other colour is replaced by a
        wildcard before the coarsening is applied. Masking is a recolouring of the points, so
        a masked feature is closed under every move. Nested masks split one large rung into a
        chain of small ones (place the pieces showing colour 0, then colour 1, ...).
        """
        orb = self.orbits[orbit]
        n = self.model.n
        keep = None if mask is None else set(int(c) for c in mask)
        name = f"orbit{orbit}.{kind}" + ("" if keep is None else "@" + ",".join(str(c) for c in sorted(keep)))

        def masked(p: tuple) -> tuple:
            return p if keep is None else tuple(c if c in keep else -1 for c in p)

        if kind in COARSENINGS:
            fn = COARSENINGS[kind]
            return _make_feature(orb, n, name, lambda b, p: fn(masked(p)))
        if kind.startswith("sub"):
            blocks = orb.sub_blocks[int(kind[3:])]

            def classify(b: int, p: tuple) -> tuple:
                groups: dict[int, list[int]] = {}
                for t, colour in enumerate(masked(p)):
                    groups.setdefault(int(blocks[b, t]), []).append(colour)
                return tuple(tuple(sorted(groups[g])) for g in sorted(groups))

            return _make_feature(orb, n, name, classify)
        raise KeyError(kind)

    def candidate_features(self) -> list[Feature]:
        """Every distinct non-constant feature this module can build, per orbit."""
        out: list[Feature] = []
        for orb in self.orbits:
            seen: set[bytes] = set()
            kinds = list(COARSENINGS) + [f"sub{i}" for i in range(len(orb.sub_blocks))]
            for kind in kinds:
                f = self.feature(orb.index, kind)
                if f.n_classes <= 1:
                    continue                            # constant: nothing to solve
                canon = _canonical_partition(f.table)
                if canon in seen:
                    continue
                seen.add(canon)
                out.append(f)
        return out

    def describe(self) -> str:
        lines = [f"{self.model.n} points, {len(self.fixed_points)} fixed, {len(self.orbits)} moving orbits"]
        for orb in self.orbits:
            classes = len({tuple(sorted(d.keys())).__hash__() for d in orb.decode_keys})
            lines.append(
                f"  orbit {orb.index}: {len(orb.points)} points = {orb.n_pieces} pieces x {orb.k} "
                f"positions, {orb.n_colours} colours, {len(orb.sub_blocks)} sub-block system(s), "
                f"first point {int(orb.points[0])} (coordinate {int(self.model.coord[orb.points[0]])})"
            )
            _ = classes
        return "\n".join(lines)


def _canonical_partition(table: np.ndarray) -> bytes:
    """Rename the classes of each slot by first appearance, so equal partitions compare equal."""
    out = np.full_like(table, -1)
    for b in range(table.shape[0]):
        order: dict[int, int] = {}
        for i, v in enumerate(table[b]):
            if v >= 0:
                out[b, i] = order.setdefault(int(v), len(order))
    return out.tobytes()


def analyse(model: PointModel) -> Structure:
    gens = model.gens
    img = np.empty_like(gens)
    for m in range(gens.shape[0]):
        img[m, gens[m]] = np.arange(model.n)          # image form: the point at g[pos] goes to pos
    orbit_of_point = np.full(model.n, -1)
    orbits: list[Orbit] = []
    fixed: list[int] = []
    for pts in point_orbits(gens):
        if len(pts) == 1:
            fixed.append(int(pts[0]))
            continue
        orb = _build_orbit(model, img, len(orbits), pts)
        orbit_of_point[pts] = orb.index
        orbits.append(orb)
    return Structure(model=model, orbits=orbits, fixed_points=np.array(fixed, dtype=np.int64),
                     orbit_of_point=orbit_of_point)
